python3 -c "import docx, lxml; print('deps ok')" 2>&1; echo "---"; python3 -c "
import docx
d=docx.Document('inputs/offer_letter_template.docx')
import re
seen=[]
def paras(doc):
    for p in doc.paragraphs: yield p
    for t in doc.tables:
        for row in t.rows:
            for c in row.cells:
                for p in c.paragraphs: yield p
    for s in doc.sections:
        for part in (s.header,s.footer,s.first_page_header,s.first_page_footer,s.even_page_header,s.even_page_footer):
            if part is None: continue
            for p in part.paragraphs: yield p
for p in paras(d):
    t=''.join(r.text for r in p.runs)
    for m in re.finditer(r'\{\{[^}]*\}\}', t):
        seen.append(m.group(0))
from collections import Counter
for k,v in Counter(seen).items(): print(v,k)
"

